const getCurrentDateString = () => {
  const d = new Date();
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

const getCurrentTimeString = () => {
  const d = new Date();
  const hours = String(d.getHours()).padStart(2, '0');
  const minutes = String(d.getMinutes()).padStart(2, '0');
  return `${hours}:${minutes}`;
};

const parsePhoneNumber = (phone) => {
  if (!phone) return { dialCode: '+91', localNumber: '' };
  const sortedCodes = [...COUNTRY_CODES].sort((a, b) => b.dialCode.length - a.dialCode.length);
  for (const c of sortedCodes) {
    if (phone.startsWith(c.dialCode)) {
      return {
        dialCode: c.dialCode,
        localNumber: phone.substring(c.dialCode.length)
      };
    }
  }
  if (phone.startsWith('+')) {
    const match = phone.match(/^\+(\d+)/);
    if (match) {
      const dial = '+' + match[1];
      return { dialCode: dial, localNumber: phone.substring(dial.length) };
    }
  }
  return { dialCode: '+91', localNumber: phone };
};

