const LoginSlideshow = () => {
  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentIndex((prevIndex) => (prevIndex + 1) % loginSlides.length);
    }, 5000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div className="w-full flex-1 flex flex-col items-center justify-center relative min-h-[460px] max-w-[600px] mx-auto select-none">
      {/* Slides Container */}
      <div className="w-full h-[400px] relative overflow-hidden flex items-center justify-center">
        {loginSlides.map((slide, index) => {
          const isActive = index === currentIndex;
          return (
            <div
              key={index}
              className={`absolute inset-0 flex flex-col items-center justify-center transition-all duration-700 ease-in-out ${
                isActive ? "opacity-100 scale-100 pointer-events-auto" : "opacity-0 scale-95 pointer-events-none"
              }`}
            >
              {/* Scaled-up SVG Vector illustration */}
              <div className="w-full h-[220px] flex items-center justify-center mb-6">
                {renderSlideVector(slide.vectorKey)}
              </div>

              {/* Slide Text Content */}
              <div className="text-center px-6 space-y-3 shrink-0">
                {/* Animated Badge */}
                <div className="inline-flex items-center gap-1.5 px-3 py-1 text-[10px] font-black uppercase tracking-widest bg-emerald-100 text-emerald-800 border border-emerald-200 rounded-full">
                  <span className="w-1.5 h-1.5 rounded-full bg-[#18ba60] animate-pulse"></span>
                  {slide.badge}
                </div>

                {/* Slide Title */}
                <h2 
                  className="text-2xl sm:text-3xl font-extrabold uppercase tracking-tight text-slate-800 leading-tight text-outline-white"
                >
                  {slide.title}
                </h2>

                {/* Slide Description */}
                <p 
                  className="text-slate-500 text-xs sm:text-sm font-semibold leading-relaxed max-w-[460px] mx-auto text-outline-white-sm"
                >
                  {slide.desc}
                </p>
              </div>
            </div>
          );
        })}
      </div>

      {/* Slide Indicators at the bottom */}
      <div className="flex items-center gap-2.5 mt-6 shrink-0">
        {loginSlides.map((_, index) => (
          <button
            key={index}
            onClick={() => setCurrentIndex(index)}
            className={`h-2 rounded-full transition-all duration-300 ${
              index === currentIndex ? "w-8 bg-[#18ba60]" : "w-2 bg-slate-300 hover:bg-slate-400"
            }`}
            type="button"
          />
        ))}
      </div>
    </div>
  );
};

